    criteriosTexto += `Evidencias esperadas:\n`;
    for (const sub of criterio.subcriterios) {
      if (sub.descripcion) criteriosTexto += `- ${sub.descripcion}\n`;
      if (sub.evidencias) {
        // Manejar tanto si viene como array o como objeto iterativo
        for (const key in sub.evidencias) {
          if (sub.evidencias.hasOwnProperty(key)) {
            criteriosTexto += `  * ${sub.evidencias[key]}\n`;
          }
        }
      }
    }
  }

  if (criterio.instrucciones_puntuacion) {
    criteriosTexto += `Instrucciones de puntuación:\n${criterio.instrucciones_puntuacion}\n`;
  }
}

// 2. Construir sección de penalizaciones si existen
let penalizacionesTexto = '';
if (rubrica.penalizaciones && rubrica.penalizaciones.length > 0) {
  penalizacionesTexto += `\n## PENALIZACIONES (A descontar de la nota si ocurren)\n`;
  for (const pen of rubrica.penalizaciones) {
    penalizacionesTexto += `- Descuento de ${pen.descuento_porcentaje}%: ${pen.descripcion}\n`;
  }
}

// 3. Construir sección de condiciones de desaprobación si existen
let condicionesTexto = '';
if (rubrica.condiciones_desaprobacion && rubrica.condiciones_desaprobacion.length > 0) {
  condicionesTexto += `\n## CONDICIONES DE DESAPROBACIÓN DIRECTA\n`;
  for (const cond of rubrica.condiciones_desaprobacion) {
    condicionesTexto += `- Si ocurre: "${cond.condicion}", la nota final debe ser ${cond.nota_final}\n`;
  }
}

// Prompt especializado para corrección de entregas PDF (ejercicios físicos, matemáticos, etc.)
