  "recomendaciones": ["<recomendación 1>", "<recomendación 2>"],
  "comentario_general": "<comentario de 2-3 oraciones>"
}

IMPORTANTE:
- Cada criterio de la rúbrica debe aparecer en la respuesta.
- Si hubo penalizaciones globales, la propiedad "nota" debe reflejar el descuento pertinente (no será igual a la suma de los criterios).
- NO incluyas texto antes o después del JSON
- NO uses markdown code blocks, solo JSON puro`;

// Construir body para Gemini API con el PDF referenciado por URI
const body = {
  generationConfig: {
    temperature: 0,
    topK: 1,
    topP: 1,
    candidateCount: 1,
    responseMimeType: "application/json",
    responseSchema: {
      type: "object",
      properties: {
        nota: { type: "number" },
        criterios: {
          type: "array",
          items: {
            type: "object",
            properties: {
              nombre: { type: "string" },
              puntaje_obtenido: { type: "number" },
              puntaje_maximo: { type: "number" },
              estado: { type: "string", enum: ["OK", "WARNING", "ERROR"] },
              feedback: { type: "string" }
            },
            required: ["nombre", "puntaje_obtenido", "puntaje_maximo", "estado", "feedback"]
          }
        },
        fortalezas: {
          type: "array",
          items: { type: "string" }
        },
        recomendaciones: {
          type: "array",
          items: { type: "string" }
        },
        comentario_general: { type: "string" }
      },
      required: ["nota", "criterios", "fortalezas", "recomendaciones", "comentario_general"]
    }
  },
  contents: [
    {
      role: "user",
      parts: [
        {
          fileData: {
            fileUri: fileUri,
            mimeType: "application/pdf"
          }
        },
        {
          text: prompt
        }
      ]
    }
  ]
};

return [{ json: { geminiBody: body, api_key: apiKey } }];

// Parser de respuesta de Gemini para corrección PDF
// Mismo patrón que correccion-workflow.json

const geminiResponse = $input.first().json;
const startTime = Date.now();

try {
  // Verificar si hay error de Gemini (503, 429, 500, etc.)
  if (geminiResponse.error) {
    const errorMsg = geminiResponse.error.message || JSON.stringify(geminiResponse.error);
    const errorCode = geminiResponse.error.code || 'UNKNOWN';

    return [{
      json: {
        success: false,
        error: {
          code: 'GEMINI_ERROR',
          message: `Error de Gemini [${errorCode}]: ${errorMsg}`,
          retry: errorCode === 503 || errorCode === 500
        }
      }
    }];
  }

  // Normalizar respuesta (puede venir como array o objeto)
  let responseArray;
  if (Array.isArray(geminiResponse)) {
    responseArray = geminiResponse;
  } else if (geminiResponse.body && Array.isArray(geminiResponse.body)) {
    responseArray = geminiResponse.body;
  } else if (geminiResponse.data && Array.isArray(geminiResponse.data)) {
    responseArray = geminiResponse.data;
  } else {
    responseArray = [geminiResponse];
  }

  const candidate = responseArray[0]?.candidates?.[0];

  if (!candidate) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: 'No se encontró candidate en respuesta de Gemini',
          retry: true
        }
      }
    }];
  }

  const textContent = candidate.content?.parts?.[0]?.text;

  if (!textContent) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: 'No se encontró texto en la respuesta',
          retry: true
        }
      }
    }];
  }

  // Parsear el JSON (responseMimeType: application/json garantiza JSON puro)
  const parsedData = JSON.parse(textContent);

  // Validar estructura mínima
  if (!parsedData.nota && parsedData.nota !== 0) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: "Respuesta no contiene campo 'nota'",
          retry: true
        }
      }
    }];
  }

  if (!Array.isArray(parsedData.criterios)) {
    return [{
      json: {
        success: false,
        error: {
          code: 'PARSING_ERROR',
          message: "Respuesta no contiene 'criterios' como array",
          retry: true
        }
      }
    }];
  }

  // Construir metadata
  const elapsedTime = Date.now() - startTime;
  const metadata = {
    modelo: 'gemini-2.5-flash',
    modo: 'vision-pdf',
    tokens_entrada: candidate.tokenCount?.totalTokens || 0,
    tokens_salida: candidate.tokenCount?.candidatesTokenCount || 0,
    tiempo_ms: elapsedTime
  };

  // Retornar resultado exitoso — mismo contrato que correccion-workflow.json
  return [{
    json: {
      success: true,
      correccion: {
        nota: parsedData.nota,
        criterios: parsedData.criterios,
        fortalezas: parsedData.fortalezas || [],
        recomendaciones: parsedData.recomendaciones || [],
        comentario_general: parsedData.comentario_general || ''
      },
      metadata: metadata
    }
  }];

} catch (error) {
  return [{
    json: {
      success: false,
      error: {
        code: 'PARSING_ERROR',
        message: `Error al procesar corrección PDF: ${error.message}`,
        retry: true
      }
    }
  }];
}
